## Refactored with Async/Await

```javascript
async function getUser(id) {
  const rows = await db.query('SELECT * FROM users WHERE id = ?', [id]);

  if (!rows.length) {
    throw new Error(`User with id ${id} not found`);
  }

  return rows[0];
}
```

### Usage

```javascript
// Basic usage
const user = await getUser(1);

// With error handling
try {
  const user = await getUser(1);
  console.log(user);
} catch (err) {
  console.error('Failed to get user:', err.message);
}
```

---

### If `db.query` Doesn't Natively Return a Promise

Wrap it using `util.promisify` or a manual Promise:

**Option A — `util.promisify` (recommended)**
```javascript
const { promisify } = require('util');
const dbQuery = promisify(db.query).bind(db);

async function getUser(id) {
  const rows = await dbQuery('SELECT * FROM users WHERE id = ?', [id]);

  if (!rows.length) {
    throw new Error(`User with id ${id} not found`);
  }

  return rows[0];
}
```

**Option B — Manual Promise wrapper**
```javascript
function queryAsync(sql, params) {
  return new Promise((resolve, reject) => {
    db.query(sql, params, (err, rows) => {
      if (err) reject(err);
      else resolve(rows);
    });
  });
}

async function getUser(id) {
  const rows = await queryAsync('SELECT * FROM users WHERE id = ?', [id]);

  if (!rows.length) {
    throw new Error(`User with id ${id} not found`);
  }

  return rows[0];
}
```

---

### Key Changes

| Before | After |
|---|---|
| `callback(err)` | `throw new Error(...)` |
| `callback(null, result)` | `return result` |
| Error-first callback pattern | Native `try/catch` |
| Nested callbacks | Linear, readable flow |

> **Tip:** Most modern database libraries (e.g., `mysql2`, `pg`, `mongoose`) support promises natively, making `util.promisify` unnecessary.
